     // `(raw << FRAME_SHIFT) == raw * pow2(FRAME_SHIFT) == raw * FRAME_SIZE`.
     lemma_usize_shl_is_mul(raw, crate::mem::FRAME_SHIFT);

     // `(raw * FRAME_SIZE) % FRAME_SIZE == 0`.
     lemma_mod_multiples_basic(raw as int, s);
